-- ===========================================================================
-- CELEB CLOSE-UP
--
-- Generated by backend/scripts/build-celeb-images.mjs. Do not hand-edit
-- the question rows; change the manifest and rebuild instead.
--
-- Adds a nullable media JSON column to questions, registers the game and
-- seeds one question per celebrity. The image files themselves live in
-- backend/public/celebrities/celeb-closeup/<slug>/.
-- ===========================================================================

SET NAMES utf8mb4;

ALTER TABLE `questions` ADD COLUMN `media` JSON NULL AFTER `options`;

INSERT INTO `mini_games`
  (code, name, emoji, tagline, category, duration_seconds, max_score, coins_per_1000, config, color_from, color_to, sort_order)
VALUES
  ('celeb-closeup', 'Celeb Close-Up', '🕵️', 'Guess the star from eyes, nose, lips and hair', 'india', 45, 1200, 10, JSON_OBJECT('questionCount', 10, 'revealAnswer', true, 'features', JSON_ARRAY('eyes','nose','lips','hair')), '#db2777', '#7c3aed', 6)
ON DUPLICATE KEY UPDATE name = VALUES(name), tagline = VALUES(tagline), duration_seconds = VALUES(duration_seconds), max_score = VALUES(max_score), coins_per_1000 = VALUES(coins_per_1000), config = VALUES(config), color_from = VALUES(color_from), color_to = VALUES(color_to), sort_order = VALUES(sort_order);

-- One question per celebrity. `media` stores the four feature crops and the
-- full portrait shown after the answer. The API strips `celebrity` before
-- sending the question to a client.

INSERT INTO `questions` (`game_id`, `prompt`, `options`, `correct_index`, `explanation`, `difficulty`, `points`, `media`)
SELECT g.id, 'Whose eyes, nose, lips and hair are these?', '["Amitabh Bachchan","Ranveer Singh","Ajay Devgn","Shah Rukh Khan"]', 3, 'Shah Rukh Khan — every close-up is from the same portrait.', 'easy', 100, '{"celebrity":"Shah Rukh Khan","eyes":"/celebrities/celeb-closeup/shah-rukh-khan/eyes.jpg","nose":"/celebrities/celeb-closeup/shah-rukh-khan/nose.jpg","lips":"/celebrities/celeb-closeup/shah-rukh-khan/lips.jpg","hair":"/celebrities/celeb-closeup/shah-rukh-khan/hair.jpg","reveal":"/celebrities/celeb-closeup/shah-rukh-khan/reveal.jpg"}'
  FROM `mini_games` g
 WHERE g.code = 'celeb-closeup' AND NOT EXISTS (SELECT 1 FROM questions q WHERE q.game_id = g.id AND JSON_UNQUOTE(JSON_EXTRACT(q.media, '$.celebrity')) = 'Shah Rukh Khan');

